function distanceKm(a,b){const R=6371,r=v=>v*Math.PI/180,dLat=r(b.lat-a.lat),dLng=r(b.lng-a.lng),x=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLng/2)**2;return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function jobDistance(j){return distanceKm(userLocation,{lat:j.lat,lng:j.lng})}
function estimateTravel(j){const km=jobDistance(j)*1.25,modes={walk:{speed:4.5,extra:0,label:'pieszo'},bike:{speed:15,extra:2,label:'rowerem'},transit:{speed:18,extra:8,label:'komunikacją'},car:{speed:28,extra:5,label:'samochodem'}},m=modes[travelMode];return{minutes:Math.max(3,Math.round(km/m.speed*60+m.extra)),label:m.label}}
function timeMatches(j){return filters.time==='all'||(filters.time==='morning'&&j.start<12)||(filters.time==='afternoon'&&j.start>=12&&j.start<17)||(filters.time==='evening'&&j.start>=17)}
function filteredJobs(){const q=document.querySelector('#searchInput').value.trim().toLowerCase();let list=jobs.filter(j=>j.active!==false&&(activeDate==='all'||activeDate===j.day)&&(aiMatchedIds===null||aiMatchedIds.includes(j.id))&&(j.role+' '+j.company+' '+j.area).toLowerCase().includes(q)&&(!locationFilterEnabled||jobDistance(j)<=filters.radius)&&j.rate>=filters.minRate&&(!filters.industries.length||filters.industries.includes(j.industry))&&timeMatches(j)&&(!filters.noExperience||!j.experience)&&(!filters.noEnglish||!j.english));const sorters={nearest:(a,b)=>jobDistance(a)-jobDistance(b),rate:(a,b)=>b.rate-a.rate,newest:(a,b)=>b.newness-a.newness,recommended:(a,b)=>b.match-a.match};return list.sort(sorters[filters.sort])}
function requirementLabel(j){if(j.english)return 'Angielski wymagany';if(j.experience)return 'Doświadczenie wymagane';return 'Bez doświadczenia'}
function renderJobs(){const list=filteredJobs();document.querySelector('#resultCount').textContent=list.length;grid.innerHTML=list.length?list.map(j=>{const trip=estimateTravel(j),travel=locationFilterEnabled?`<span>⌖ ${jobDistance(j).toFixed(1).replace('.',',')} km</span><span class="travel-time">~${trip.minutes} min ${trip.label}</span>`:'';return`<article class="job-card" data-id="${j.id}"><div class="job-cover" style="--cover:${j.color}"><div class="company-logo">${j.icon}</div><span class="match">${j.match}% DOPASOWANIA</span></div><div class="job-body"><h3>${j.role}</h3><span class="company">${j.company} · ${j.area}</span><div class="job-meta"><span>▣ ${j.date}, ${j.time}</span>${travel}<span class="requirement-tag">${requirementLabel(j)}</span></div><div class="job-footer"><div><strong>${j.rate*(j.end-j.start)} zł</strong><small> · ${j.rate} zł/h</small></div><button>${booked.includes(j.id)?'Zapisano ✓':'Zobacz'}</button></div></div></article>`}).join(''):'<div class="empty"><strong>Brak zmian spełniających kryteria</strong><br><br>Zmień grafik, zwiększ promień albo usuń część filtrów.</div>';document.querySelectorAll('.job-card').forEach(el=>el.onclick=()=>openJob(+el.dataset.id));renderFilterSummary()}
function renderFilterSummary(){const chips=[];if(aiMatchedIds!==null)chips.push('Wybrane przez AI');if(locationFilterEnabled)chips.push(`Lokalizacja · do ${filters.radius} km`);if(filters.minRate)chips.push(`Od ${filters.minRate} zł/h`);if(filters.industries.length)chips.push(`${filters.industries.length} branże`);if(filters.time!=='all')chips.push({morning:'Rano',afternoon:'Popołudnie',evening:'Wieczór'}[filters.time]);if(filters.noExperience)chips.push('Bez doświadczenia');if(filters.noEnglish)chips.push('Bez angielskiego');document.querySelector('#activeFilters').innerHTML=chips.map(x=>`<span class="filter-chip">${x}</span>`).join('');const badge=document.querySelector('#filterCount');badge.textContent=chips.length;badge.classList.toggle('visible',chips.length>0);const bar=document.querySelector('.location-bar');bar.classList.toggle('inactive',!locationFilterEnabled);document.querySelector('#locationLabel').textContent=locationFilterEnabled?`${userLocation.label} · do ${filters.radius} km`:'Lokalizacja wyłączona';document.querySelector('#clearLocation').hidden=!locationFilterEnabled;document.querySelector('#mapClearLocation').hidden=!locationFilterEnabled}
function openJob(id){const j=jobs.find(x=>x.id===id),d=getJobDetails(j),pay=j.rate*(j.end-j.start);const publicPart=`<div class="modal-hero" style="background:${j.color}"><div class="company-logo">${j.icon}</div><p class="eyebrow">${j.match}% DOPASOWANIA · ${jobDistance(j).toFixed(1).replace('.',',')} KM</p><h2>${j.role}</h2><p>${j.company} · ${j.area}</p></div><div class="modal-body"><div class="modal-details"><div class="detail"><small>Kiedy</small><strong>${j.date}<br>${j.time}</strong></div><div class="detail"><small>Wynagrodzenie</small><strong>${pay} zł<br>${j.rate} zł/h</strong></div></div>`;if(!authUser){jobModal.querySelector('#modalContent').innerHTML=publicPart+`<div class="guest-job-preview"><h3>Informacje ogólne</h3><p>Krótka, elastyczna zmiana w dzielnicy ${j.area}. Dokładny adres, kontakt do pracodawcy, obowiązki i instrukcje organizacyjne są dostępne po zalogowaniu.</p><div class="locked-details"><div class="lock-icon">🔒</div><strong>Szczegóły dostępne po zalogowaniu</strong><p>Założenie konta jest bezpłatne i nie zobowiązuje Cię do przyjęcia zmiany.</p></div><button class="login-details-button">Zaloguj się i zobacz szczegóły</button></div></div>`;jobModal.showModal();jobModal.querySelector('.login-details-button').onclick=()=>openAuth('login',()=>openJob(id));return}jobModal.querySelector('#modalContent').innerHTML=publicPart+`<div class="details-section"><h3>Miejsce i kontakt</h3><div class="private-details-grid"><div class="private-detail wide"><small>DOKŁADNY ADRES</small><strong>⌖ ${d.address}</strong></div><div class="private-detail"><small>OSOBA KONTAKTOWA</small><strong>${d.contactName}</strong></div><div class="private-detail"><small>TELEFON SŁUŻBOWY</small><strong><a href="tel:${d.contactPhone.replace(/\s/g,'')}">${d.contactPhone}</a></strong></div></div></div><div class="details-section"><h3>Przygotowanie do zmiany</h3><div class="instruction-list"><div class="instruction-row"><span>◷</span><div><strong>Przyjście</strong><small>${d.arrival}</small></div></div><div class="instruction-row"><span>♙</span><div><strong>Strój</strong><small>${d.dressCode}</small></div></div><div class="instruction-row"><span>▤</span><div><strong>Dokumenty</strong><small>${d.documents}</small></div></div><div class="instruction-row"><span>ⓘ</span><div><strong>Dodatkowe informacje</strong><small>${d.instructions}</small></div></div></div></div><div class="details-section"><h3>Zakres obowiązków</h3><ul>${j.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><p><strong>Wymagania:</strong> ${requirementLabel(j)}</p></div><button class="book-button" data-book="${j.id}">${booked.includes(j.id)?'Anuluj zapis':'Biorę tę zmianę'}</button><p class="details-notice">Klikając przycisk, potwierdzasz znajomość szczegółów i gotowość do realizacji zmiany.</p></div>`;jobModal.showModal();jobModal.querySelector('[data-book]').onclick=()=>toggleBook(id)}
function toggleBook(id){booked=booked.includes(id)?booked.filter(x=>x!==id):[...booked,id];localStorage.setItem('flexo-booked',JSON.stringify(booked));jobModal.close();renderJobs();renderBooked();renderDashboardSummary();toast(booked.includes(id)?'Zmiana jest Twoja! Szczegóły znajdziesz w kalendarzu.':'Zapis na zmianę został anulowany.')}
function renderBooked(){const list=booked.map(id=>jobs.find(j=>j.id===id)).filter(Boolean);document.querySelector('#shiftCount').textContent=list.length;document.querySelector('#bookedList').innerHTML=list.length?list.map(j=>`<article class="booked-card"><div class="date-tile"><small>${j.date.slice(0,3).toUpperCase()}</small><strong>${j.start}</strong></div><div class="grow"><h3>${j.role}</h3><p>${j.company} · ${j.time} · ${j.area}</p><strong>${j.rate*(j.end-j.start)} zł</strong></div><button class="primary" onclick="openJob(${j.id})">Szczegóły</button></article>`).join(''):'<div class="empty">Nie masz jeszcze zaplanowanych zmian.</div>'}
function switchView(id){if(id==='admin'&&authUser?.role!=='admin'){toast('Panel administratora jest dostępny tylko dla administratorów.');id='discover'}if(id==='employer'&&!['employer','admin'].includes(authUser?.role)){toast('Panel pracodawcy wymaga konta firmowego.');id='discover'}document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active-view',v.id===id));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}
function locateUser(showMapAfter=false){const status=document.querySelector('#geoStatus');status.textContent='Pobieram lokalizację…';if(!navigator.geolocation)return toast('Ta przeglądarka nie obsługuje geolokalizacji.');navigator.geolocation.getCurrentPosition(p=>{userLocation={lat:p.coords.latitude,lng:p.coords.longitude,label:'Twoja lokalizacja'};locationFilterEnabled=true;status.textContent=`Dokładność: ${Math.round(p.coords.accuracy)} m`;renderJobs();if(showMapAfter){if(filterModal.open)filterModal.close();if(!document.querySelector('#mapModal').open)openMap()}if(jobsMap){jobsMap.setView([userLocation.lat,userLocation.lng],13);updateMap()}toast('Lokalizacja została ustawiona — wybierz ofertę na mapie.')},()=>{status.textContent='Brak dostępu';toast('Zezwól przeglądarce na dostęp do lokalizacji.')},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})}
function syncFilterForm(){document.querySelector('#radiusInput').value=filters.radius;document.querySelector('#radiusOutput').value=filters.radius;document.querySelector(`[name="rate"][value="${filters.minRate}"]`).checked=true;document.querySelectorAll('[name="industry"]').forEach(x=>x.checked=filters.industries.includes(x.value));document.querySelector('#timeFilter').value=filters.time;document.querySelector('#noExperience').checked=filters.noExperience;document.querySelector('#noEnglish').checked=filters.noEnglish}
function readFilterForm(){filters.radius=+document.querySelector('#radiusInput').value;filters.minRate=+document.querySelector('[name="rate"]:checked').value;filters.industries=[...document.querySelectorAll('[name="industry"]:checked')].map(x=>x.value);filters.time=document.querySelector('#timeFilter').value;filters.noExperience=document.querySelector('#noExperience').checked;filters.noEnglish=document.querySelector('#noEnglish').checked}
function clearFilters(){filters={...filters,radius:10,minRate:0,industries:[],time:'all',noExperience:false,noEnglish:false};syncFilterForm()}
function clearAiResults(){aiMatchedIds=null;renderJobs()}
function parseAssistant(text){const t=text.toLowerCase().replace(/,/g,' '),days={monday:/poniedział|poniedzial/,tuesday:/wtorek|wtorku/,wednesday:/środ|srod/};let day=Object.keys(days).find(k=>days[k].test(t));const windows=[...t.matchAll(/(?:od\s*)?(\d{1,2})(?::\d{2})?\s*(?:-|–|do)\s*(\d{1,2})(?::\d{2})?/g)].map(m=>[+m[1],+m[2]]);const after=t.match(/po\s+(\d{1,2})/),before=t.match(/(?:przed|do)\s+(\d{1,2})/);if(!windows.length&&after)windows.push([+after[1],24]);if(!windows.length&&before)windows.push([0,+before[1]]);const rateMatch=t.match(/(?:minimum|min\.?|od)\s*(\d{2})\s*zł/),radiusMatch=t.match(/(?:do|promieniu)\s*(\d{1,2})\s*km/);const industries=[];if(/biur|recepc/.test(t))industries.push('office');if(/event|wydarze/.test(t))industries.push('events');if(/sklep|retail|inwent/.test(t))industries.push('retail');if(/logisty|magaz|paczk|przesył/.test(t))industries.push('logistics');if(/teren|ankiet/.test(t))industries.push('field');return{day,windows,minRate:rateMatch?+rateMatch[1]:0,radius:radiusMatch?+radiusMatch[1]:null,industries}}
function assistantSearch(text){const p=parseAssistant(text);let matches=jobs.filter(j=>j.active!==false&&(!p.day||j.day===p.day)&&(!p.windows.length||p.windows.some(([a,b])=>j.start>=a&&j.end<=b))&&j.rate>=p.minRate&&(!p.radius||jobDistance(j)<=p.radius)&&(!p.industries.length||p.industries.includes(j.industry)));return{parsed:p,matches}}
function addChat(text,type){const el=document.createElement('div');el.className=`chat-message ${type}`;el.innerHTML=text;document.querySelector('#assistantChat').appendChild(el);document.querySelector('#assistantChat').scrollTop=99999;return el}
function handleAssistant(text){if(!text.trim())return;addChat(text,'user');const {parsed,matches}=assistantSearch(text);setTimeout(()=>{const understood=[parsed.day&&({monday:'poniedziałek',tuesday:'wtorek',wednesday:'środę'}[parsed.day]),parsed.windows.length&&parsed.windows.map(x=>`${x[0]}:00–${x[1]}:00`).join(' lub '),parsed.minRate&&`min. ${parsed.minRate} zł/h`,parsed.radius&&`do ${parsed.radius} km`].filter(Boolean).join(', ');const cards=matches.map(j=>`<div class="ai-result"><div><strong>${j.role}</strong><small>${j.date} · ${j.time} · ${j.area}</small></div><b>${j.rate} zł/h</b></div>`).join('');const msg=matches.length?`Rozumiem: <strong>${understood||'elastyczny grafik'}</strong>. Znalazłem ${matches.length} ${matches.length===1?'pasującą zmianę':'pasujące zmiany'}:${cards}<button class="show-ai-results">Pokaż te oferty</button>`:`Rozumiem: <strong>${understood||'podane preferencje'}</strong>. Nie mam teraz idealnego dopasowania. Spróbuj poszerzyć godziny albo promień.`;const el=addChat(msg,'bot');const btn=el.querySelector('.show-ai-results');if(btn)btn.onclick=()=>{aiMatchedIds=matches.map(j=>j.id);activeDate='all';document.querySelectorAll('.filter[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));assistantModal.close();renderJobs();toast('Pokazuję oferty wybrane przez asystenta.')}} ,350)}
function openAssistant(){assistantModal.showModal();setTimeout(()=>document.querySelector('#assistantPrompt').focus(),100)}
function initials(){return `${userProfile.firstName[0]||''}${userProfile.lastName[0]||''}`.toUpperCase()}
function renderGreeting(){document.querySelector('#heroGreeting').textContent=authUser?.role==='user'?`Cześć, ${authUser.firstName}!`:'Cześć!'}
