async function drawRouteToJob(id,fit=true){if(!locationFilterEnabled)return toast('Najpierw ustaw punkt startowy lub użyj swojej lokalizacji.');const job=jobs.find(j=>j.id===id);if(!job)return;selectedMapJobId=id;const requestId=++routeRequestId,profiles={walk:'foot',bike:'bike',transit:'car',car:'car'},profile=profiles[travelMode],url=`https://routing.openstreetmap.de/routed-${profile}/route/v1/driving/${userLocation.lng},${userLocation.lat};${job.lng},${job.lat}?overview=full&geometries=geojson`;const modeIcons={walk:'🚶',bike:'🚲',transit:'🚌',car:'🚗'},summary=document.querySelector('#routeSummary');document.querySelector('#routeIcon').textContent=modeIcons[travelMode];document.querySelector('#routeJobName').textContent=job.role;document.querySelector('#routeMeta').textContent='Wyznaczam trasę po drogach…';summary.hidden=false;try{const response=await fetch(url);if(!response.ok)throw new Error('routing');const data=await response.json();if(requestId!==routeRequestId||!data.routes?.length)return;const route=data.routes[0],points=route.geometry.coordinates.map(([lng,lat])=>[lat,lng]);if(routeLine)jobsMap.removeLayer(routeLine);routeLine=L.polyline(points,{color:'#0d5b48',weight:5,opacity:.9}).addTo(jobsMap);let minutes=Math.max(1,Math.round(route.duration/60));if(travelMode==='transit')minutes=Math.round(minutes*1.25+8);const label=travelMode==='transit'?'komunikacją (orientacyjnie)':estimateTravel(job).label;document.querySelector('#routeMeta').textContent=`${(route.distance/1000).toFixed(1).replace('.',',')} km · około ${minutes} min ${label}`;if(fit)jobsMap.fitBounds(routeLine.getBounds().pad(.15),{maxZoom:15})}catch(error){if(requestId!==routeRequestId)return;document.querySelector('#routeMeta').textContent='Nie udało się teraz wyznaczyć trasy. Spróbuj ponownie.';toast('Serwis trasowania jest chwilowo niedostępny.')}}
function clearLocationFilter(){locationFilterEnabled=false;clearRoute();renderJobs();updateMap();toast('Filtrowanie według lokalizacji zostało wyłączone.')}
function updateMap(){if(!jobsMap)return;startMarker.setLatLng([userLocation.lat,userLocation.lng]).setOpacity(locationFilterEnabled?1:.45);radiusCircle.setLatLng([userLocation.lat,userLocation.lng]).setRadius(filters.radius*1000).setStyle({opacity:locationFilterEnabled?1:0,fillOpacity:locationFilterEnabled?0.16:0});jobMapLayer.clearLayers();let count=0;jobs.filter(j=>j.active!==false).forEach(j=>{const within=!locationFilterEnabled||jobDistance(j)<=filters.radius,trip=estimateTravel(j);if(within)count++;const popup=`<div class="map-job-popup"><strong>${j.role}</strong><small>${j.company} · ${j.area}</small><small>${j.date}, ${j.time} · ${j.rate} zł/h</small>${locationFilterEnabled?`<small>${jobDistance(j).toFixed(1).replace('.',',')} km · około ${trip.minutes} min ${trip.label}</small>`:''}<button onclick="openMapJob(${j.id})">Zobacz zlecenie →</button></div>`,marker=L.circleMarker([j.lat,j.lng],{radius:within?9:6,color:within?'#0d5b48':'#8f9c97',fillColor:within?'#d8ff70':'#d9dfdc',fillOpacity:1,weight:2,opacity:within?1:.55,bubblingMouseEvents:false}).addTo(jobMapLayer).bindPopup(popup,{minWidth:190});marker.on('click',()=>drawRouteToJob(j.id,true))});document.querySelector('#mapJobsCount').textContent=count;document.querySelector('#mapLocationLabel').textContent=locationFilterEnabled?userLocation.label:'Nie wybrano';document.querySelector('#mapRadiusOutput').value=filters.radius;document.querySelector('#mapRadius').value=filters.radius;document.querySelector('#mapClearLocation').hidden=!locationFilterEnabled;document.querySelector('#clearLocation').hidden=!locationFilterEnabled;if(selectedMapJobId&&locationFilterEnabled)drawRouteToJob(selectedMapJobId,false)}
function openMap(){document.querySelector('#mapModal').showModal();document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===travelMode));initMap()}
function fitAllMapJobs(){if(!jobsMap)return;const points=jobs.filter(j=>j.active!==false).map(j=>[j.lat,j.lng]);if(locationFilterEnabled)points.push([userLocation.lat,userLocation.lng]);if(points.length)jobsMap.fitBounds(L.latLngBounds(points).pad(.18),{maxZoom:13});toast('Mapa pokazuje wszystkie aktywne oferty.')}
